def is_power_of_5(x):
    if x <= 0:
        return False
    while x > 1 and x % 5 == 0:
        x //= 5
    return x == 1

results = []
for n in range(3, 21):
    x = (2**n) - 3
    if is_power_of_5(x):
        # If it is a power of 5, find k such that 5^k = x
        k = 0
        temp_x = x
        while temp_x > 1:
            temp_x //= 5
            k += 1
        results.append((n, k))

print("Found pairs (n, k):")
for pair in results:
    print(pair)

def is_power_of_five(N):
    """Checks if a positive integer N is a power of 5."""
    if N <= 0:
        return False
    if N == 1:
        return True # 5^0 = 1
    while N > 1:
        if N % 5 != 0:
            return False
        N //= 5
    return True

# Candidate values for n: 27, 31, 35, 39, 43, 47
candidates = [27, 31, 35, 39, 43, 47]
results = {}

for n in candidates:
    X = (2**n) - 3
    is_power = is_power_of_five(X)
    results[n] = is_power
    print(f"n={n}: 2^{n} - 3 = {X}. Is it a power of 5? {is_power}")

print("\nSummary:", results)

def power_mod(base, exponent, modulus):
    return pow(base, exponent, modulus)

MOD = 125
TARGET = 3
N_MAX = 125 # Search up to the order of 2 mod 125

solutions_n = []
for n in range(1, N_MAX + 1):
    if power_mod(2, n, MOD) == TARGET:
        solutions_n.append(n)

print(f"Solutions n for 2^n = 3 (mod 125): {solutions_n}")

